"""
patch_beep_sound.py — Phase 7.2: swap siren for a beep, confirm heads-up settings
====================================================================================
Two changes from the previous patch:

  1. core/sounds/jarvis_alert.mp3 / .ogg — replaced with a short, sharp
     double-beep (security-alarm chirp style) instead of the longer
     radar/siren/glitch sound. Same filenames as before, so fcm_push.py
     and the Service Worker (which both just reference "jarvis_alert")
     do not need any changes.

  2. core/alert.html — playback logic rewritten. The old siren clip used
     audio.loop = true, which is fine for a continuous sound but would
     just stutter a short beep back-to-back with no gap. This version
     explicitly replays the beep every 900ms with a clean gap, and pulses
     vibration in sync with each repeat.

This patch does NOT touch fcm_push.py or mobile_server.py — the Android
notification's visibility="public" (shows on lock screen) and
priority="max" (heads-up banner) are already in place from the previous
patch. If heads-up / lock-screen display still isn't happening on your
phone after this, it's almost always one of:
  - The "jarvis_intrusion" notification channel got muted/downgraded by
    Android the first time it fired (Settings -> Apps -> Chrome ->
    Notifications -> jarvis_intrusion -> make sure it's not Silent/Off)
  - Do Not Disturb is on and the channel isn't allowed to override it
  - Lock screen notification visibility is restricted at the OS level
    (Settings -> Notifications -> "Sensitive notifications" / "Notifications
    on lock screen" set to hide content)

Run once from the project root:
    python patch_beep_sound.py
"""
from __future__ import annotations
import base64
from pathlib import Path

BASE_DIR = Path(__file__).resolve().parent
CORE_DIR = BASE_DIR / "core"
SOUNDS_DIR = BASE_DIR / "core" / "sounds"

MP3_B64 = ""
OGG_B64 = ""


def backup(path: Path):
    if path.exists():
        bak = path.with_suffix(path.suffix + ".bak_beep")
        if not bak.exists():
            bak.write_bytes(path.read_bytes())


def write_sounds():
    SOUNDS_DIR.mkdir(parents=True, exist_ok=True)
    mp3_path = SOUNDS_DIR / "jarvis_alert.mp3"
    ogg_path = SOUNDS_DIR / "jarvis_alert.ogg"
    backup(mp3_path)
    backup(ogg_path)
    mp3_path.write_bytes(base64.b64decode(MP3_B64))
    ogg_path.write_bytes(base64.b64decode(OGG_B64))
    print("[1] Beep sound written -> core/sounds/jarvis_alert.{mp3,ogg} (replaces siren)")


def write_alert_html():
    src = BASE_DIR / "_new_alert_html_beep.html"
    dest = CORE_DIR / "alert.html"
    if src.exists():
        backup(dest)
        dest.write_bytes(src.read_bytes())
        print("[2] core/alert.html replaced -- beep-repeat cadence + synced vibration")
    else:
        print("[2] WARNING: _new_alert_html_beep.html not found next to this script -- skipped alert.html")


def main():
    write_sounds()
    write_alert_html()

    print()
    print("====================================================")
    print("Beep-sound patch applied.")
    print("Next steps:")
    print("  1. Restart JARVIS: python jarvis_service.pyw")
    print("  2. On your phone: open the ngrok URL once, wait 5s, close Chrome")
    print("  3. Win+L -> wrong password -> unlock")
    print("  4. You should hear a sharp double-beep (repeating every ~0.9s)")
    print("     instead of the siren, both in the notification sound and")
    print("     on the full-screen page once you tap into it.")
    print()
    print("If the notification still doesn't show on your lock screen or")
    print("as a heads-up banner, check (see this file's docstring for detail):")
    print("  - Settings -> Apps -> Chrome -> Notifications -> jarvis_intrusion channel")
    print("  - Do Not Disturb exceptions")
    print("  - Lock screen notification content visibility setting")
    print("====================================================")


if __name__ == "__main__":
    main()